:root {
  --bg: #ffffff;
  --bg-secondary: #f8fafc;
  --bg-hover: #f1f5f9;
  --border: #e2e8f0;
  --text: #0f172a;
  --text-muted: #64748b;
  --primary: #0284c7;
  --primary-hover: #0369a1;
  --primary-light: #e0f2fe;
  --success: #16a34a;
}

@media (prefers-color-scheme: dark) {
  :root {
    --bg: #0f172a;
    --bg-secondary: #1e293b;
    --bg-hover: #334155;
    --border: #334155;
    --text: #f8fafc;
    --text-muted: #94a3b8;
    --primary: #38bdf8;
    --primary-hover: #7dd3fc;
    --primary-light: #082f49;
    --success: #4ade80;
  }
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  padding: 0;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  background-color: var(--bg);
  color: var(--text);
  overflow: hidden;
  user-select: none;
}

.syno-container {
  display: flex;
  flex-direction: column;
  height: 100vh;
  width: 100vw;
  background: var(--bg);
}

/* Header bar */
.syno-header {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 16px;
  border-bottom: 1px solid var(--border);
  background: var(--bg-secondary);
}

.syno-brand {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  font-weight: 500;
  color: var(--text);
  flex-shrink: 0;
}

.syno-status-badge {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-size: 11px;
  padding: 2px 7px;
  border-radius: 9999px;
  background: rgba(34, 197, 94, 0.12);
  color: var(--success);
}

.syno-status-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background-color: var(--success);
}

.syno-search-bar {
  display: flex;
  align-items: center;
  gap: 8px;
  flex: 1;
  background: var(--bg);
  border: 1px solid var(--border);
  border-radius: 6px;
  padding: 4px 10px;
}

.syno-search-input {
  border: none;
  outline: none;
  background: transparent;
  width: 100%;
  font-size: 12px;
  color: var(--text);
}

.syno-search-input::placeholder {
  color: var(--text-muted);
}

.syno-search-clear {
  border: none;
  background: transparent;
  padding: 0;
  cursor: pointer;
  color: var(--text-muted);
  display: flex;
  align-items: center;
}

.syno-search-clear:hover {
  color: var(--text);
}

.syno-sort-select {
  border: 1px solid var(--border);
  background: var(--bg);
  color: var(--text);
  font-size: 12px;
  border-radius: 6px;
  padding: 4px 8px;
  outline: none;
  cursor: pointer;
}

/* Breadcrumbs & Share tags */
.syno-nav-section {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 8px 16px;
  border-bottom: 1px solid var(--border);
  background: var(--bg);
}

.syno-breadcrumbs {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 4px;
  font-size: 12px;
}

.syno-crumb {
  border: none;
  background: transparent;
  color: var(--text-muted);
  cursor: pointer;
  padding: 2px 4px;
  border-radius: 4px;
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

.syno-crumb:hover {
  background: var(--bg-hover);
  color: var(--text);
}

.syno-crumb.is-current {
  color: var(--text);
}

.syno-crumb-sep {
  color: var(--text-muted);
  font-size: 11px;
}

.syno-shares-bar {
  display: flex;
  align-items: center;
  gap: 6px;
  overflow-x: auto;
  padding-bottom: 2px;
}

.syno-share-chip {
  border: 1px solid var(--border);
  background: var(--bg-secondary);
  color: var(--text-muted);
  font-size: 11px;
  padding: 3px 8px;
  border-radius: 12px;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 4px;
  white-space: nowrap;
}

.syno-share-chip:hover {
  background: var(--bg-hover);
  color: var(--text);
}

.syno-share-chip.is-active {
  background: var(--primary-light);
  border-color: var(--primary);
  color: var(--primary);
}

/* Content List Area */
.syno-content-area {
  flex: 1;
  overflow-y: auto;
  padding: 4px 0;
}

.syno-file-list {
  display: flex;
  flex-direction: column;
}

.syno-file-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8px 16px;
  border-bottom: 1px solid rgba(226, 232, 240, 0.4);
  cursor: pointer;
  font-size: 13px;
}

.syno-file-row:hover {
  background: var(--bg-hover);
}

.syno-file-main {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
  flex: 1;
}

.syno-file-icon {
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
}

.syno-file-info {
  display: flex;
  flex-direction: column;
  min-width: 0;
}

.syno-file-name {
  color: var(--text);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.syno-file-path-sub {
  font-size: 11px;
  color: var(--text-muted);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.syno-file-meta {
  display: flex;
  align-items: center;
  gap: 16px;
  flex-shrink: 0;
  font-size: 12px;
  color: var(--text-muted);
}

.syno-file-actions {
  display: flex;
  align-items: center;
